INSERT INTO articles (slug,title,teaser,body,category,topic,region,kind,author,image,source_name,source_url,status,published_at,updated_at,meta_title,meta_description,focus_keyword,keywords,image_alt,image_prompt,faq,service) VALUES ('wohnbaufoerderung-oesterreich-2025-baubewilligungen-iibw-sanierung','Wohnbauförderung Österreich: Mehr Geld, aber weniger Baubewilligungen','Die Länder haben 2025 so viel Geld in die Wohnbauförderung gesteckt wie lange nicht. Trotzdem wurden weniger Wohnungen bewilligt – Sanierung wird zum Hauptmotor.','Die **Wohnbauförderung in Österreich** hat 2025 ein Ausgabenniveau erreicht, das es zuletzt in den 2000er- und frühen 2010er-Jahren gab. Gleichzeitig ist die Zahl der Baubewilligungen erneut gesunken. Das zeigt die jährliche Wohnbauförderungs- und Baubewilligungsstatistik, die das Institut für Immobilien, Bauen und Wohnen (IIBW) gemeinsam mit dem Fachverband der Stein- und keramischen Industrie erstellt und am Mittwoch präsentiert hat.

## Baubewilligungen 2025: Ein Drittel unter dem Schnitt

Insgesamt wurden im Vorjahr rund 47.800 Wohneinheiten bewilligt, gezählt werden dabei Wohnungen in neuen und in bestehenden Gebäuden. Das sind um 3 Prozent weniger als 2024 und etwa ein Drittel weniger als im Durchschnitt der vergangenen zehn Jahre. Noch deutlicher fällt das Minus beim reinen Neubau aus: Wohnungen in neu errichteten Gebäuden liegen 42 Prozent unter dem Zehnjahresmittel.

Eine Trendwende ist laut Studie nicht in Sicht. Für 2026 erwarten die Autoren einen weiteren Rückgang um 7 bis 8 Prozent. Am stärksten trifft es den freifinanzierten Geschoßwohnbau, also Wohnungen ohne öffentliche Förderung.

## Wohnbauförderung Österreich: Ausgaben steigen auf 2,68 Milliarden

Auf der Förderseite zeigt sich ein anderes Bild. Die Länder gaben 2025 rund 2,68 Milliarden Euro für die Wohnbauförderung aus, ein Plus von 7 Prozent gegenüber dem Jahr davor. Damit liegen die Ausgaben fast ein Viertel über dem Zehnjahresdurchschnitt, seit 2022 sind sie um 41 Prozent gewachsen. Bund und Länder zusammen wenden für Wohnungspolitik 0,9 Prozent der Wirtschaftsleistung auf, die Länder allein 0,6 Prozent.

Die Förderzusicherungen stiegen leicht auf 19.800 Wohneinheiten (plus 3 Prozent):

- **Geschoßwohnbau:** 14.600 geförderte Einheiten, knapp unter dem Vorjahr
- **Eigenheime:** 5.200 geförderte Einheiten, ein Zuwachs von rund einem Drittel
- **Gesamt:** weiterhin 13 Prozent unter dem Zehnjahresmittel

## Wohnbaurate: Tirol vorne, Niederösterreich hinten

Zwischen den Bundesländern gibt es große Unterschiede. Österreichweit kamen 2025 auf 1.000 Einwohnerinnen und Einwohner 3,5 bewilligte Wohnungen. Deutlich darüber lagen:

1. Tirol mit 6,2
2. Burgenland mit 4,9
3. Vorarlberg mit 4,8
4. Wien mit 4,4

Unter dem Österreich-Schnitt blieben Salzburg (2,7), die Steiermark (2,6), Kärnten (2,4) und Niederösterreich mit 2,2 bewilligten Wohnungen pro 1.000 Einwohner.

## Sanierung wird zum wichtigsten Förderfeld

Auffällig ist die Verschiebung in Richtung Bestand. Die Länder stellten 2025 rund 740 Millionen Euro für Sanierungen bereit. Gemeinsam mit der Umweltförderung des Bundes flossen damit etwa 2,3 Milliarden Euro in die Wohnhaussanierung. Das ist beinahe das Zweieinhalbfache des Zehnjahresschnitts und mehr, als für die Förderung von Neubauten ausgegeben wurde. Für 2027 ist eine neue Sanierungsoffensive mit 321 Millionen Euro für thermische Sanierung angekündigt.

Für Eigentümerinnen und Eigentümer heißt das: Wer ein Haus oder eine Wohnung thermisch sanieren, Fenster tauschen oder die Fassade dämmen will, findet derzeit vergleichsweise viele Fördertöpfe. Welche Programme gelten, hängt vom Bundesland ab, Beratungsstellen der Länder helfen bei der Antragstellung.

## Was die Branche jetzt fordert

IIBW-Geschäftsführer Wolfgang Amann und der Fachverband sehen mehrere Hebel, um den Wohnbau wieder anzukurbeln. Gefordert werden bessere Finanzierungsbedingungen für Bauwillige, eine Wohnrechtsnovelle mit einem Paket zur Dekarbonisierung und einem klaren Schwerpunkt auf Sanierung sowie Förderperspektiven, die über 2027 hinaus planbar sind. Nur so könnten Bauträger und Haushalte längerfristig kalkulieren, heißt es in der Aussendung.

Die vollständigen Zahlen sind in der Broschüre „Wohnbauförderung in Österreich 2025“ zusammengefasst, die über die Websites der Baustoffindustrie und des IIBW abrufbar ist.','bauen-wohnen','Bauen',NULL,'news','Presseinfo Redaktion','/assets/img/artikel/wohnbaufoerderung-oesterreich-2025-baubewilligungen-iibw-sanierung.webp','Fachverband der Stein- und keramischen Industrie / IIBW (APA-OTS)','https://www.ots.at/presseaussendung/OTS_20261028_OTS0037/wohnbaufoerderungs-und-baubewilligungsstatistik-2025','published','2026-10-28T14:50:00.000Z','2026-10-28T14:44:30.083Z','Wohnbauförderung Österreich: 2,68 Mrd. Euro im Jahr 2025','Wohnbauförderung Österreich 2025: Die Länder zahlen 2,68 Mrd. Euro, doch Baubewilligungen sinken. Alle Zahlen zu Bundesländern und Sanierung im Überblick.','Wohnbauförderung Österreich','["Wohnbauförderung","Wohnbauförderung Österreich","Baubewilligungen 2025","Wohnbaurate Bundesländer","Sanierungsförderung","Wohnhaussanierung 2025","IIBW Wohnbaustatistik","Sanierungsoffensive 2027","Eigenheimförderung"]','Wohnbauförderung Österreich: Wohnhaus mit Gerüst während einer thermischen Sanierung','Austrian multi-storey residential building under renovation with scaffolding and fresh facade insulation panels, autumn afternoon, a tower crane in the background, suburban Austrian town with hills, realistic','[{"q":"Wie viel Geld floss 2025 in die Wohnbauförderung?","a":"Die Länder gaben laut IIBW rund 2,68 Milliarden Euro aus, um 7 Prozent mehr als 2024."},{"q":"Wie viele Wohnungen wurden 2025 bewilligt?","a":"Rund 47.800 Wohneinheiten, um 3 Prozent weniger als im Vorjahr und ein Drittel unter dem Zehnjahresschnitt."},{"q":"Welches Bundesland hat die höchste Wohnbaurate?","a":"Tirol mit 6,2 bewilligten Wohnungen pro 1.000 Einwohner, Niederösterreich hat mit 2,2 die niedrigste."}]',1) ON CONFLICT(slug) DO UPDATE SET title=excluded.title, teaser=excluded.teaser, body=excluded.body, category=excluded.category, topic=excluded.topic, region=excluded.region, kin